func TestWiresharkDebuggerWritesOriginalKeyFormats(t *testing.T) {
	path := filepath.Join(t.TempDir(), "swu.keys")
	debugger, err := NewWiresharkDebugger(true, path)
	if err != nil {
		t.Fatalf("NewWiresharkDebugger: %v", err)
	}
	debugger.LogIKESAKeys(1, 2, []byte{0x11}, []byte{0x22}, []byte{0x33}, []byte{0x44}, 12, 12)
	debugger.LogChildSA(3, 4, "192.0.2.1", "198.51.100.1", []byte{0x55}, []byte{0x66}, 20)
	debugger.LogRaw("message %d", 7)
	if err := debugger.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	info, err := os.Stat(path)
	if err != nil {
		t.Fatalf("Stat: %v", err)
	}
	if info.Mode().Perm() != 0o600 {
		t.Fatalf("key log mode = %o", info.Mode().Perm())
	}
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("ReadFile: %v", err)
	}
	for _, expected := range []string{
		"# IKEv2/ESP Decryption Table", "# Generated by swu-go at ",
		`"IKEv2" "0000000000000001" "0000000000000002" "11" "22" "33" "44" "12" "12"`,
		`"ESP" "0x00000003" "198.51.100.1" "192.0.2.1" "55" "20"`,
		`"ESP" "0x00000004" "192.0.2.1" "198.51.100.1" "66" "20"`,
		"# message 7",
	} {
		if !bytes.Contains(content, []byte(expected)) {
			t.Fatalf("key log missing %q:\n%s", expected, content)
		}
	}
}

func TestWiresharkKeyLogOpensAtIKEKeyInstallation(t *testing.T) {
	path := filepath.Join(t.TempDir(), "missing", "swu.keys")
	session := NewSession(&Config{EnableWiresharkKeyLog: true, WiresharkKeyLogPath: path})
	if session.initErr != nil || session.debug != nil {
		t.Fatalf("NewSession touched deferred key log: init=%v debug=%v", session.initErr, session.debug)
	}
	session.Ni = bytes.Repeat([]byte{0x11}, 32)
	session.spiI = ikeSPIBytes(1)
	session.spiR = ikeSPIBytes(2)
	session.dhSharedSecret = bytes.Repeat([]byte{0x22}, 32)
	if err := session.GenerateIKESAKeys(bytes.Repeat([]byte{0x33}, 32)); err == nil {
		t.Fatal("IKE key installation hid the key-log open failure")
	}
	if session.ikeKeys != nil || session.Keys != nil {
		t.Fatal("failed key-log setup installed IKE key material")
	}
}

func TestWiresharkKeyLogInitializationRacesWithShutdown(t *testing.T) {
	for range 100 {
		path := filepath.Join(t.TempDir(), "swu.keys")
		session := NewSession(&Config{EnableWiresharkKeyLog: true, WiresharkKeyLogPath: path})
		started := make(chan struct{})
		done := make(chan struct{})
		go func() {
			close(started)
			_ = session.ensureWiresharkDebugger()
			close(done)
		}()
		<-started
		session.Shutdown()
		<-done
		if session.currentWiresharkDebugger() != nil {
			t.Fatal("shutdown retained a concurrently initialized debugger")
		}
		if err := session.ensureWiresharkDebugger(); !errors.Is(err, context.Canceled) {
			t.Fatalf("post-shutdown debugger initialization error = %v", err)
		}
	}
}

func TestSessionWritesKeysFromProductionInstallPaths(t *testing.T) {
	path := filepath.Join(t.TempDir(), "swu.keys")
	session := NewSession(&Config{EnableWiresharkKeyLog: true, WiresharkKeyLogPath: path})
	session.setTransport(newTestIKETransport())
	session.Ni = bytes.Repeat([]byte{0x11}, 32)
	session.spiI = ikeSPIBytes(1)
	session.spiR = ikeSPIBytes(2)
	session.dhSharedSecret = bytes.Repeat([]byte{0x22}, 32)
	if err := session.GenerateIKESAKeys(bytes.Repeat([]byte{0x33}, 32)); err != nil {
		t.Fatalf("GenerateIKESAKeys: %v", err)
	}
	session.innerIP = net.IPv4(10, 0, 0, 8)
	session.espLocalSPI, session.espRemoteSPI = 3, 4
	session.childNi = bytes.Repeat([]byte{0x44}, 32)
	session.childNr = bytes.Repeat([]byte{0x55}, 32)
	session.childTSi, session.childTSr = buildTrafficSelectorsForIPStack(session.innerIP)
	if err := session.setupDataPlane(); err != nil {
		t.Fatalf("setupDataPlane: %v", err)
	}
	session.Shutdown()
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("ReadFile: %v", err)
	}
	if !strings.Contains(string(content), `"IKEv2"`) || !strings.Contains(string(content), `"ESP"`) {
		t.Fatalf("production key log omitted IKE or ESP rows:\n%s", content)
	}
}

func TestDataPlaneStatsLoopWritesAllRecoveredCounters(t *testing.T) {
	core, observed := observer.New(zapcore.DebugLevel)
	session := NewSession(&Config{}, zap.New(core))
	stats := &dataPlaneRuntimeStats{}
	stats.tunRead.Store(1)
	stats.espSend.Store(2)
	stats.lastInSPI.Store(0x10203040)
	stats.lastPlainLen.Store(3)
	stats.lastTunReadLen.Store(4)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() {
		session.logDataPlaneStats(ctx, DataplaneModeTUN, stats, time.Millisecond)
		close(done)
	}()
	waitForSWuCondition(t, func() bool { return observed.Len() > 0 })
	cancel()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("stats loop did not stop after context cancellation")
	}
	entry := observed.All()[0]
	if entry.Message != "SWu dataplane stats" {
		t.Fatalf("stats message = %q", entry.Message)
	}
	fields := entry.ContextMap()
	for _, name := range []string{
		"mode", "tunRead", "espSend", "espSendError", "espOutSAMiss",
		"espEncapError", "espIn", "espInSAMiss", "espDecapError",
		"tunWrite", "tunWriteError", "lastInSPI", "lastPlainLen", "lastTunReadLen",
	} {
		if _, ok := fields[name]; !ok {
			t.Errorf("stats log missing field %q", name)
		}
	}
	if fields["mode"] != DataplaneModeTUN {
		t.Fatalf("stats fields = %#v", fields)
	}
}

func TestSessionStatsLoopUsesRecoveredLifecycle(t *testing.T) {
	core, observed := observer.New(zapcore.DebugLevel)
	session := NewSession(&Config{}, zap.New(core))
	done := make(chan struct{})
	go func() {
		session.logSessionStats(time.Millisecond)
		close(done)
	}()
	waitForSWuCondition(t, func() bool { return observed.Len() > 0 })
	session.cancel()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("session stats loop did not stop after cancellation")
	}
	entry := observed.All()[0]
	if entry.Message != "SWu session stats" || entry.ContextMap()["state"] != stateIdle {
		t.Fatalf("session stats entry = %+v", entry)
	}
}
